package main
import("os";"fmt";"bufio";"encoding/json")
func compilePhaseBarrier(stage string) {
 if os.Getenv("WASMVM_COMPILE_PHASE")!="1" {return}
 if err:=json.NewEncoder(os.Stdout).Encode(map[string]string{"compilePhase":stage});err!=nil{panic(err)}
 line,err:=bufio.NewReader(os.Stdin).ReadString('\n');if err!=nil||line!="phase\n"{panic(fmt.Sprintf("phase barrier: %q %v",line,err))}
}
